export function isMathCorrect(exercise,answer){return answer===exercise.answer;}
export function cleanMathProgress(value){return {completed:Array.isArray(value?.completed)?[...new Set(value.completed.filter(id=>mathExercises.some(e=>e.id===id)))]:[]};}
export function distribution(total,groups,steps){const placed=Math.max(0,Math.min(total,steps));return Array.from({length:groups},(_,i)=>Math.floor(placed/groups)+(i<placed%groups?1:0));}
